insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 24, 'Então Josué, e todo Israel com ele, tomou a Acã filho de zerá, e o dinheiro, e o manto, e a barra de ouro, e seus filhos, e suas filhas, e seus bois, e seus asnos, e suas ovelhas, e sua tenda, e tudo quanto tinha, e levaram-no tudo ao vale de Acor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 25, 'E disse Josué: Por que nos perturbaste? Perturbe-te o SENHOR neste dia. E todos os israelitas os apedrejaram, e os queimaram a fogo, depois de apedrejá-los com pedras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 26, 'E levantaram sobre ele um grande amontoado de pedras, até hoje. E o SENHOR se apaziguou da ira de seu furor. E por isto foi chamado aquele lugar o Vale de Acor, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 1, 'E o SENHOR disse a Josué: Não temas, nem desmaies; toma contigo toda a gente de guerra, e levanta-te e sobe a Ai. Olha, eu entreguei em tua mão ao rei de Ai, e a seu povo, a sua cidade, e a sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 2, 'E farás a Ai e a seu rei como fizeste a Jericó e a seu rei: somente que seus despojos e seus animais tomareis para vós. Porás, pois, emboscadas à cidade detrás dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 3, 'E levantou-se Josué, e toda a gente de guerra, para subir contra Ai: e escolheu Josué trinta mil homens fortes, os quais enviou de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 4, 'E mandou-lhes, dizendo: Olhai, poreis emboscada à cidade detrás dela: não vos afastareis muito da cidade, e estareis todos prontos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 5, 'E eu, e todo aquele povo que está comigo, nos aproximaremos da cidade; e quando saírem eles contra nós, como fizeram antes, fugiremos diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 6, 'E eles sairão atrás de nós, até que os tiremos da cidade; porque eles dirão: Fogem de nós como a primeira vez. Fugiremos, pois, diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 7, 'Então vós vos levantareis da emboscada, e vos lançareis sobre a cidade; pois o SENHOR vosso Deus a entregará em vossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 8, 'E quando a houverdes tomado, poreis fogo nela. Fareis conforme a palavra do SENHOR. Olhai que vos o mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 9, 'Então Josué os enviou; e eles se foram à emboscada, e puseram-se entre Betel e Ai, ao ocidente de Ai: e Josué ficou aquela noite em meio do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 10, 'E levantando-se Josué muito de manhã, revistou ao povo, e subiu ele, com os anciãos de Israel, diante do povo contra Ai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 11, 'E toda a gente de guerra que com ele estava, subiu, e aproximou-se, e chegaram diante da cidade, e assentaram o campo à parte do norte de Ai: e o vale estava entre ele e Ai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 12, 'E tomou como cinco mil homens, e os pôs em emboscada entre Betel e Ai, à parte ocidental da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 13, 'E o povo, todo aquele acampamento que estava à parte do norte da cidade, colocado já próximo, e sua emboscada ao ocidente da cidade, veio Josué aquela noite ao meio do vale.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 14, 'O qual quando o rei de Ai viu, levantou-se prontamente de manhã, e saiu com a gente da cidade contra Israel, ele e todo seu povo, para combater pela planície ao tempo assinalado, não sabendo que lhe estava posta emboscada atrás da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 15, 'Então Josué e todo Israel, fazendo-se de vencidos, fugiram diante deles pelo caminho do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 16, 'E todo aquele povo que estava em Ai se juntou para segui-los: e seguiram a Josué, sendo assim tirados da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 17, 'E não ficou homem em Ai e Betel, que não tivesse saído atrás de Israel; e por perseguir a Israel deixaram a cidade aberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 18, 'Então o SENHOR disse a Josué: Levanta a lança que tens em tua mão até Ai, porque eu a entregarei em tua mão. E Josué levantou até a cidade a lança que em sua mão tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 19, 'E levantando-se prontamente de seu lugar os que estavam na emboscada, correram logo que ele levantou sua mão, e vieram à cidade, e a tomaram, e apressaram-se a por-lhe fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 20, 'E quando os da cidade olharam atrás, observaram, e eis que a fumaça da cidade que subia ao céu, e não puderam fugir nem a uma parte nem à outra: e o povo que ia fugindo até o deserto, se voltou contra os que o seguiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 21, 'Josué e todo Israel, vendo que os da emboscada tomaram a cidade, e que a fumaça da cidade subia, voltaram, e feriram aos de Ai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 22, 'E os outros saíram da cidade a seu encontro: e assim foram cercados em meio de Israel, os uns da uma parte, e os outros da outra. E os feriram até que não restou nenhum deles que escapasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 23, 'E tomaram vivo ao rei de Ai, e trouxeram-lhe a Josué.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 24, 'E quando os israelitas acabaram de matar a todos os moradores de Ai no campo, no deserto, onde eles os haviam perseguido, e que todos haviam caído a fio de espada até serem consumidos, todos os israelitas se voltaram a Ai, e também a feriram à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 25, 'E o número dos que caíram aquele dia, homens e mulheres, foi doze mil, todos os de Ai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 26, 'E Josué não retraiu sua mão que havia estendido com a lança, até que destruiu a todos os moradores de Ai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 27, 'Porém os israelitas tomaram para si os animais e os despojos da cidade, conforme a palavra do SENHOR que ele havia mandado a Josué.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 28, 'E Josué queimou a Ai e reduziu-a a um amontoado perpétuo, assolado até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 29, 'Mas ao rei de Ai enforcou de um madeiro até à tarde: e quando o sol se pôs, mandou Josué que tirassem do madeiro seu corpo, e o lançassem à porta da cidade: e levantaram sobre ele um grande amontoado de pedras, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 30, 'Então Josué edificou um altar ao SENHOR Deus de Israel no monte de Ebal,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 31, 'Como Moisés, servo do SENHOR, o havia mandado aos filhos de Israel, como está escrito no livro da lei de Moisés, um altar de pedras inteiras sobre as quais ninguém levantou ferro: e ofereceram sobre ele holocaustos ao SENHOR, e sacrificaram ofertas pacíficas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 32, 'Também escreveu ali em pedras a repetição da lei de Moisés, a qual ele havia escrito diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 33, 'E todo Israel, e seus anciãos, oficiais, e juízes, estavam da uma e da outra parte junto à arca, diante dos sacerdotes levitas que levam a arca do pacto do SENHOR; tanto estrangeiros como naturais, a metade deles estava até o monte de Gerizim, e a outra metade até o monte de Ebal; da maneira que Moisés, servo do SENHOR, havia lhe mandado antes, para que abençoassem primeiramente ao povo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 34, 'Depois disto, leu todas as palavras da lei, as bênçãos e as maldições, conforme tudo o que está escrito no livro da lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 8, 35, 'Não houve palavra alguma de todas as coisas que mandou Moisés, que Josué não fizesse ler diante de toda a congregação de Israel, mulheres e meninos, e estrangeiros que andavam entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 1, 'E aconteceu que quando ouviram estas coisas todos os reis que estavam desta parte do Jordão, tanto nas montanhas como nas planícies, e em toda a costa do grande mar diante do Líbano, os heteus, amorreus, cananeus, perizeus, heveus, e jebuseus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 2, 'Juntaram-se em unidade, de um acordo, para lutar contra Josué e Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 3, 'Mas os moradores de Gibeão, quando ouviram o que Josué havia feito a Jericó e a Ai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 4, 'Eles usaram também de astúcia; pois foram e fingiram-se embaixadores, e tomaram sacos anciãos sobre seus asnos, e odres anciãos de vinho, rasgados e remendados,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 5, 'E sapatos velhos e remendados em seus pés, com roupas velhas sobre si; e todo aquele pão que traziam para o caminho, seco e mofado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 6, 'Assim vieram a Josué ao acampamento em Gilgal, e disseram-lhe a ele e aos de Israel: Nós viemos da terra muito distante: fazei, pois, agora conosco aliança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 7, 'E os de Israel responderam aos heveus: Talvez vós habiteis em meio de nós: como pois poderemos nós fazer aliança convosco?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 8, 'E eles responderam a Josué: Nós somos teus servos. E Josué lhes disse: Quem sois vós e de onde vindes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 9, 'E eles responderam: Teus servos vieram de muito distantes terras, pela fama do SENHOR teu Deus; porque ouvimos sua fama, e todas as coisas que fez em Egito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 10, 'E tudo o que fez aos dois reis dos amorreus que estavam da outra parte do Jordão; a Seom rei de Hesbom, e a Ogue rei de Basã, que estava em Astarote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 11, 'Pelo qual nossos anciãos e todos os moradores de nossa terra nos disseram: Tomai em vossas mãos provisão para o caminho, e ide ao encontro deles, e dizei-lhes: Nós somos vossos servos, e fazei agora conosco aliança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 12, 'Este nosso pão tomamos quente de nossas casas para o caminho o dia que saímos para vir a vós; e ei-lo aqui agora que está seco e mofado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 13, 'Estes odres de vinho também os enchemos novos; ei-los aqui já rasgados: também estes nossas roupas e nossos sapatos estão já velhos por causa do muito longo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 14, 'E os homens de Israel tomaram de sua provisão do caminho, e não perguntaram à boca do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 15, 'E Josué fez paz com eles, e estabeleceu com eles que lhes deixaria a vida: também os príncipes da congregação lhes juraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 16, 'Passados três dias depois que fizeram com eles o concerto, ouviram como eram seus vizinhos, e que habitavam em meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 17, 'E partiram-se os filhos de Israel, e ao terceiro dia chegaram a suas cidades: e suas cidades eram Gibeão, Quefira, Beerote, e Quiriate-Jearim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 18, 'E não os feriram os filhos de Israel, porquanto os príncipes da congregação lhes haviam jurado pelo SENHOR o Deus de Israel. E toda a congregação murmurava contra os príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 19, 'Mas todos os príncipes responderam a toda a congregação: Nós lhes juramos pelo SENHOR Deus de Israel; portanto, agora não lhes podemos tocar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 20, 'Isto faremos com eles: lhes deixaremos viver, para que não venha ira sobre nós por causa do juramento que lhes fizemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 21, 'E os príncipes lhes disseram: Vivam; mas sejam lenhadores e carregadores de água para toda a congregação, como os príncipes lhes disseram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 22, 'E chamando-os Josué, lhes falou dizendo: Por que nos enganastes, dizendo, Habitamos muito longe de vós; uma vez que morais em meio de nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 23, 'Vós pois agora sois malditos, e não faltará de vós servo, e quem corte a lenha e tire a água para a casa de meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 24, 'E eles responderam a Josué, e disseram: Quando foi dado a entender a teus servos, que o SENHOR teu Deus havia mandado a Moisés seu servo que vos havia de dar toda a terra, e que havia de destruir todos os moradores da terra diante de vós, por isto temos muito medo de vós por nossas vidas, e fizemos isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 25, 'Agora pois, eis-nos aqui em tua mão; o que te parecer bom e correto fazer de nós, faze-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 26, 'E ele o fez assim; que os livrou da mão dos filhos de Israel, para que não os matassem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 9, 27, 'E constituiu-os Josué aquele dia por lenhadores e carregadores de água para a congregação e para o altar do SENHOR, no lugar que ele escolhesse: o que são até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 1, 'E quando Adoni-Zedeque rei de Jerusalém ouviu que Josué havia tomado a Ai, e que a haviam assolado, (como havia feito a Jericó e a seu rei, assim fez a Ai e a seu rei;) e que os moradores de Gibeão fizeram paz com os israelitas, e que estavam entre eles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 2, 'Tiveram muito grande temor; porque Gibeão era uma grande cidade, como uma das cidades reais, e maior que Ai, e todos os seus homens fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 3, 'Enviou, pois, a dizer Adoni-Zedeque rei de Jerusalém, a Hoão rei de Hebrom, e a Pirã rei de Jeremote, e a Jafia rei de Laquis, e a Debir rei de Eglom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 4, 'Subi a mim, e ajudai-me, e combatamos a Gibeão: porque fez paz com Josué e com os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 5, 'E cinco reis dos amorreus, o rei de Jerusalém, o rei de Hebrom, o rei de Jeremote, o rei de Laquis, o rei de Eglom, se juntaram e subiram, eles com todos os seus exércitos, e assentaram acampamento sobre Gibeão, e lutaram contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 6, 'E os moradores de Gibeão enviaram a dizer a Josué ao acampamento em Gilgal: Não encolhas tuas mãos de teus servos; sobe prontamente a nós para guardar-nos e ajudar-nos: porque todos os reis dos amorreus que habitam nas montanhas, se juntaram contra nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 7, 'E subiu Josué de Gilgal, ele e todo aquele povo de guerra com ele, e todos os homens valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 8, 'E o SENHOR disse a Josué: Não tenhas medo deles: porque eu os entreguei em tua mão, e nenhum deles resistirá diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 9, 'E Josué veio a eles de repente, toda a noite subiu desde Gilgal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 10, 'E o SENHOR os perturbou diante de Israel, e feriu-os com grande mortandade em Gibeão: e seguiu-os pelo caminho que sobe a Bete-Horom, e feriu-os até Azeca e Maceda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 11, 'E quando iam fugindo dos israelitas, à descida de Bete-Horom, o SENHOR lançou sobre eles do céu grandes pedras até Azeca, e morreram: muitos mais morreram das pedras do granizo, que os que os filhos de Israel haviam matado à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 12, 'Então Josué falou ao SENHOR o dia que o SENHOR entregou aos amorreus diante dos filhos de Israel, e disse em presença dos israelitas: Sol, detém-te em Gibeão; E tu, Lua, no vale de Aijalom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 13, 'E o sol se deteve e a lua se parou, Até tanto que a gente se havia vingado de seus inimigos. Não está este escrito no livro de Jasar? E o sol se parou em meio do céu, e não se apressou a se pôr quase um dia inteiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 14, 'E nunca foi tal dia antes nem depois daquele, havendo atendido o SENHOR à voz de um homem: porque o SENHOR lutava por Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 15, 'E Josué, e todo Israel com ele, voltava-se ao acampamento em Gilgal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 16, 'Porém os cinco reis fugiram, e se esconderam em uma cova em Maquedá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 17, 'E foi dito a Josué que os cinco reis haviam sido achados em uma cova em Maquedá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 18, 'Então Josué disse: Rolai grandes pedras à boca da cova, e ponde homens junto a ela que os guardem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 19, 'E vós não vos pareis, mas sim segui a vossos inimigos, e feri-lhes a retaguarda, sem deixar-lhes entrar em suas cidades; porque o SENHOR vosso Deus os entregou em vossa mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 20, 'E aconteceu que quando Josué e os filhos de Israel acabaram de feri-los com mortandade muito grande, até destruí-los, os que restaram deles se meteram nas cidades fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 21, 'E todo aquele povo se voltou salvo ao acampamento a Josué em Maquedá; que não houve quem movesse sua língua contra os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 22, 'Então disse Josué: Abri a boca da cova, e tirai-me dela a estes cinco reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 23, 'E fizeram-no assim, e tiraram-lhe da cova aqueles cinco reis: ao rei de Jerusalém, ao rei de Hebrom, ao rei de Jeremote, ao rei de Laquis, ao rei de Eglom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 24, 'E quando tiraram estes reis a Josué, chamou Josué a todos os homens de Israel, e disse aos principais da gente de guerra que haviam vindo com ele: Chegai e ponde vossos pés sobre os pescoços destes reis. E eles se aproximaram, e puseram seus pés sobre os pescoços deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 25, 'E Josué lhes disse: Não temais, nem vos atemorizeis; sede fortes e valentes: porque assim fará o SENHOR a todos vossos inimigos contra os quais lutai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 26, 'E depois disto Josué os feriu e os matou, e os fez enforcar em cinco madeiros: e restaram enforcados nos madeiros até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 27, 'E quando o sol se ia a pôr, mandou Josué que os tirassem dos madeiros, e os lançassem na cova de onde se haviam escondido: e puseram grandes pedras à boca da cova, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 28, 'Naquele mesmo dia tomou Josué a Maquedá, e a pôs à espada, e matou a seu rei; a eles e a tudo o que nela tinha vida, sem restar nada: mas ao rei de Maquedá fez como havia feito ao rei de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 29, 'E de Maquedá passou Josué, e todo Israel com ele, a Libna; e lutou contra Libna:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 30, 'E o SENHOR a entregou também a ela, e a seu rei, em mãos de Israel; e feriu-a a fio de espada, com tudo o que nela havia vivo, sem restar nada: mas a seu rei fez da maneira que havia feito ao rei de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 31, 'E Josué, e todo Israel com ele, passou de Libna a Laquis, e pôs acampamento contra ela, e combateu-a:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 32, 'E o SENHOR entregou a Laquis em mão de Israel, e tomou-a ao dia seguinte, e feriu-a à espada, com tudo o que nela havia vivo, como havia feito em Libna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 33, 'Então Horão, rei de Gezer, subiu em ajuda de Laquis; mas a ele e a seu povo feriu Josué, até não restar nenhum deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 34, 'De Laquis passou Josué, e todo Israel com ele, a Eglom: e puseram acampamento contra ela, e combateram-na:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 35, 'E a tomaram no mesmo dia, e meteram-na à espada; e aquele dia matou a todo o que nela havia vivo, como havia feito em Laquis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 36, 'Subiu logo Josué, e todo Israel com ele, de Eglom a Hebrom, e combateram-na;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 37, 'E tomando-a, feriram-na à espada, a seu rei e a todas as suas cidades, com tudo o que nela havia vivo, sem restar nada: como fizeram a Eglom, assim a destruíram com tudo o que nela havia vivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 38, 'E voltando-se Josué, e todo Israel com ele, sobre Debir, combateu-a;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 39, 'E tomou-a, e a seu rei, e a todas as suas vilas; e feriram-nos à espada, e destruíram tudo o que ali dentro havia vivo, sem restar nada; como havia feito a Hebrom, assim fez a Debir e a seu rei; e como havia feito a Libna e a seu rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 40, 'Feriu pois Josué toda a região das montanhas, e do sul, e das planícies, e das costas, e a todos os seus reis, sem restar nada; tudo o que tinha vida matou, ao modo que o SENHOR Deus de Israel o havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 41, 'E feriu-os Josué desde Cades-Barneia até Gaza, e toda a terra de Gósen até Gibeão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 42, 'Todos estes reis e suas terras tomou Josué de uma vez; porque o SENHOR o Deus de Israel lutava por Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 10, 43, 'E voltou Josué, e todo Israel com ele, ao acampamento em Gilgal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 1, 'Ouvindo isto Jabim rei de Hazor, enviou mensagem a Jobabe rei de Madom, e ao rei de Sinrom, e ao rei de Acsafe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 2, 'E aos reis que estavam à parte do norte nas montanhas, e na planície ao sul de Quinerete, e nas planícies, e nas regiões de Dor ao ocidente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 3, 'E aos cananeus que estava ao oriente e ao ocidente, e aos amorreus, e ao Heteu, e aos perizeus, e aos jebuseus nas montanhas, e aos heveus debaixo de Hermom em terra de Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 4, 'Estes saíram, e com eles todos os seus exércitos, povo muito em grande maneira, como a areia que está à beira do mar, com grande multidão de cavalos e carros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 5, 'Todos estes reis se juntaram, e vindo reuniram os acampamentos junto às águas de Merom, para lutar contra Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 6, 'Mas o SENHOR disse a Josué: Não tenhas medo deles, que amanhã a esta hora eu entregarei a todos estes, mortos diante de Israel: a seus cavalos aleijarás, e seus carros queimarás ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 7, 'E veio Josué, e com ele todo aquele povo de guerra, contra eles, e deu de repente sobre eles junto às águas de Merom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 8, 'E entregou-os o SENHOR em mãos de Israel, os quais os feriram e seguiram até a grande Sidom, e até as águas quentes, e até a planície de Mispá ao oriente, ferindo-os até que não lhes deixaram ninguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 9, 'E Josué fez com eles como o SENHOR lhe havia mandado: aleijou seus cavalos, e seus carros queimou ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 10, 'E voltando-se Josué, tomou no mesmo tempo a Hazor, e feriu à espada a seu rei: a qual Hazor havia sido antes cabeça de todos estes reinos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 11, 'E feriram à espada todo quanto nela havia vivo, destruindo e não deixando coisa com vida; e a Hazor puseram a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 12, 'Também tomou Josué todas as cidades destes reis, e a todos os reis delas, e os meteu à espada, e os destruiu, como Moisés servo do SENHOR o havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 13, 'Porém todas as cidades que estavam em suas colinas, não as queimou Israel, tirando a só Hazor, a qual queimou Josué.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 14, 'E os filhos de Israel tomaram para si todos os despojos e animais daquelas cidades: mas a todos os homens feriram à espada até destruí-los, sem deixar alguém com vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 15, 'Da maneira que o SENHOR o havia mandado a Moisés seu servo, assim Moisés o mandou a Josué: e assim Josué o fez, sem tirar palavra de tudo o que o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 16, 'Tomou, pois, Josué toda aquela terra, as montanhas, e toda a região do sul, e toda a terra de Gósen, e os terrenos baixos e as planícies, e a região montanhosa de Israel e seus vales.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 17, 'Desde o monte de Halaque, que sobe até Seir, até Baal-Gade na planície do Líbano, às raízes do monte Hermom: tomou também todos os seus reis, os quais feriu e matou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 18, 'Por muitos dias teve guerra Josué com estes reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 19, 'Não houve cidade que fizesse paz com os filhos de Israel, a não ser os heveus, que moravam em Gibeão: tudo o tomaram por guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 20, 'Porque isto veio do SENHOR, que endurecia o coração deles para que resistissem com guerra a Israel, para destruí-los, e que não lhes fosse feita misericórdia, antes fossem desarraigados, como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 21, 'Também no mesmo tempo veio Josué e destruiu os anaquins dos montes, de Hebrom, de Debir, e de Anabe, e de todos os montes de Judá, e de todos os montes de Israel: Josué os destruiu a eles e a suas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 22, 'Nenhum dos anaquins restou na terra dos filhos de Israel; somente restaram em Gaza, em Gate, e em Asdode.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 11, 23, 'Tomou, pois, Josué toda a terra, conforme todo o que o SENHOR havia dito a Moisés; e entregou-a Josué aos israelitas por herança, conforme suas repartições de suas tribos: e a terra repousou de guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 1, 'Estes são os reis da terra que os filhos de Israel feriram, e cuja terra possuíram da outra parte do Jordão ao oriente, desde o ribeiro de Arnom até o monte Hermom, e toda a planície oriental:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 2, 'Seom rei dos amorreus, que habitava em Hesbom, e senhoreava desde Aroer, que está à beira do ribeiro de Arnom, e desde em meio do ribeiro, e a metade de Gileade, até o ribeiro Jaboque, o termo dos filhos de Amom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 3, 'E desde a campina até o mar de Quinerete, ao oriente; e até o mar da planície, o mar Salgado, ao oriente, pelo caminho de Bete-Jesimote; e desde o sul debaixo das encostas do Pisga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 4, 'E os termos de Ogue rei de Basã, que havia restado dos refains, o qual habitava em Astarote e em Edrei,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 5, 'E senhoreava no monte de Hermom, e em Salcá, e em todo Basã até os termos de Gessuri e dos maacatitas, e a metade de Gileade, termo de Seom rei de Hesbom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 6, 'A estes feriram Moisés servo do SENHOR e os filhos de Israel; e Moisés servo do SENHOR deu aquela terra em possessão aos rubenitas, gaditas, e à meia tribo de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 7, 'E estes são os reis da terra que feriu Josué com os filhos de Israel, desta parte do Jordão ao ocidente, desde Baal-Gade na planície do Líbano até o monte de Halaque que sobe a Seir; a qual terra deu Josué em possessão às tribos de Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 8, 'Em montes e em vales, em planícies e em encostas, ao deserto e ao sul; os heteus, e os amorreus, e os cananeus, e os ferezeus, e os heveus, e os jebuseus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 9, 'O rei de Jericó, um: o rei de Ai, que está ao lado de Betel, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 10, 'O rei de Jerusalém, outro: o rei de Hebrom, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 11, 'O rei de Jarmute, outro: o rei de Laquis, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 12, 'O rei de Eglom, outro: o rei de Gezer, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 13, 'O rei de Debir, outro: o rei de Geder, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 14, 'O rei de Hormá, outro: o rei de Arade, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 15, 'O rei de Libna, outro: o rei de Adulão, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 16, 'O rei de Maquedá, outro: o rei de Betel, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 17, 'O rei de Tapua, outro: o rei de Héfer, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 18, 'O rei de Afeque, outro: o rei de Lasarom, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 19, 'O rei de Madom, outro: o rei de Hazor, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 20, 'O rei de Sinrom-Merom, outro: o rei de Acsafe, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 21, 'O rei de Taanaque, outro: o rei de Megido, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 22, 'O rei de Quedes, outro: o rei de Jocneão do Carmelo, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 23, 'O rei de Dor, da província de Dor, outro; o rei de nações em Gilgal, outro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 12, 24, 'O rei de Tirsa, outro: trinta e um reis ao todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 1, 'E sendo Josué já velho, cheio de dias, o SENHOR lhe disse: Tu és já velho, de idade avançada, e resta ainda muita terra por possuir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 2, 'Esta é a terra que resta; todos os termos dos filisteus, e todos os gessuritas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 3, 'Desde Sior, que está diante do Egito, até o termo de Ecrom ao norte, considera-se dos cananeus: cinco províncias dos filisteus; os gazitas, asdoditas, asquelonitas, giteus, e ecronitas; e os heveus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 4, 'Ao sul toda a terra dos cananeus, e Meara que é dos sidônios, até Afeque, até o termo dos amorreus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 5, 'E a terra dos gebalitas, e todo o Líbano até o oriente, desde Baal-Gade o pdo monte Hermom, até entrar em Hamate;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 6, 'Todos os que habitam nas montanhas desde o Líbano até as águas quentes, todos os sidônios; eu os desarraigarei diante dos filhos de Israel:;somente repartirás tu por sorte aquela terra aos israelitas por herança, como te mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 7, 'Reparte, pois, tu agora esta terra em herança às nove tribos, e à meia tribo de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 8, 'Porque a outra meia recebeu sua herança com os rubenitas e gaditas, a qual lhes deu Moisés da outra parte do Jordão ao oriente, segundo que se a deu Moisés servo do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 9, 'Desde Aroer, que está à beira do ribeiro de Arnom, e a cidade que está em meio do ribeiro, e toda a campina de Medeba, até Dibom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 10, 'E todas as cidades de Seom rei dos amorreus, o qual reinou em Hesbom, até os termos dos filhos de Amom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 11, 'E Gileade, e os termos dos gessuritas, e dos maacatitas, e todo o monte de Hermom, e toda a terra de Basã até Salcá:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 12, 'Todo o reino de Ogue em Basã, o qual reinou em Astarote e Edrei, o qual havia ficados do resto dos refains; pois Moisés os feriu, e expulsou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 13, 'Mas aos dos gessuritas e dos maacatitas não expulsaram os filhos de Israel; antes Gessur e Maacate habitaram entre os israelitas até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 14, 'Porém à tribo de Levi não deu herança: os sacrifícios do SENHOR Deus de Israel são sua herança, como ele lhes havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 15, 'Deu, pois, Moisés à tribo dos filhos de Rúben conforme suas famílias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 16, 'E foi o termo deles desde Aroer, que está à beira do ribeiro de Arnom, e a cidade que está em meio do ribeiro, e toda a campina, até Medeba;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 17, 'Hesbom, com todas as suas vilas que estão na planície; Dibom, e Bamote-Baal, e Bete-Baal-Meom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 18, 'E Jaza, e Quedemote, e Mefaate,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 19, 'E Quiriataim, e Sibma, e Zerete-Saar no monte do vale;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 20, 'E Bete-Peor, e as encostas de Pisga, e Bete-Jesimote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 21, 'E todas as cidades da campina, e todo o reino de Seom rei dos amorreus, que reinou em Hesbom, ao qual feriu Moisés, e aos príncipes de Midiã, Evi, Requém, e Sur, e Hur, e Reba, príncipes de Seom que habitavam naquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 22, 'Também mataram à espada os filhos de Israel a Balaão adivinho, filho de Beor, com os demais que mataram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 23, 'E foram os termos dos filhos de Rúben o Jordão com seu termo. Esta foi a herança dos filhos de Rúben conforme suas famílias, estas cidades com suas vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 24, 'Deu também Moisés à tribo de Gade, aos filhos de Gade, conforme suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 25, 'E o termo deles foi Jazer, e todas as cidades de Gileade, e a metade da terra dos filhos de Amom até Aroer, que está diante de Rabá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 26, 'E desde Hesbom até Ramate-Mispa, e Betonim; e desde Maanaim até o termo de Debir:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 27, 'E a campina de Bete-Arã, e Bete-Ninra, e Sucote, e Zafom, resto do reino de Seom, rei em Hesbom: o Jordão e seu termo até a extremidade do mar de Quinerete da outra parte do Jordão ao oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 28, 'Esta é a herança dos filhos de Gade, por suas famílias, estas cidades com suas vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 29, 'Também deu Moisés herança à meia tribo de Manassés: e foi da meia tribo dos filhos de Manassés, conforme suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 30, 'O termo deles foi desde Maanaim, todo Basã, todo o reino de Ogue rei de Basã, e todas as aldeias de Jair que estão em Basã, sessenta povoações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 31, 'Deram-se também a metade de Gileade, e Astarote, e Edrei, cidades do reino de Ogue em Basã, aos filhos de Maquir, filho de Manassés, à metade dos filhos de Maquir conforme suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 32, 'Isto é o que Moisés repartiu em herança nas planícies de Moabe, da outra parte do Jordão de Jericó, ao oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 13, 33, 'Mas à tribo de Levi não deu Moisés herança: o SENHOR Deus de Israel é a herança deles como ele lhes havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 1, 'Isto, pois, é o que os filhos de Israel tomaram por herança na terra de Canaã, o qual lhes repartiram Eleazar sacerdote, e Josué filho de Num, e os principais dos pais das tribos dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 2, 'Por sorte deu-se a eles sua herança, como o SENHOR o havia mandado por Moisés, que desse às nove tribos e à meia tribo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 3, 'Porque às duas tribos, e à meia tribo, lhes havia Moisés dado herança da outra parte do Jordão: mas aos levitas não deu herança entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 4, 'Porque os filhos de José foram duas tribos, Manassés e Efraim: e não deram parte aos levitas na terra, mas sim cidades em que morassem, com seus campos para seus gados e rebanhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 5, 'Da maneira que o SENHOR o havia mandado a Moisés, assim o fizeram os filhos de Israel na repartição da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 6, 'E os filhos de Judá vieram a Josué em Gilgal; e Calebe, filho de Jefoné quenezeu, lhe disse: Tu sabes o que o SENHOR disse a Moisés, homem de Deus, em Cades-Barneia, tocante a mim e a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 7, 'Eu era de idade de quarenta anos, quando Moisés servo do SENHOR me enviou de Cades-Barneia a reconhecer a terra; e eu lhe mencionei o negócio como o tinha em meu coração:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 8, 'Mas meus irmãos, os que haviam subido comigo, minguaram o coração do povo; porém eu cumpri seguindo ao SENHOR meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 9, 'Então Moisés jurou, dizendo: Se a terra que pisou teu pé não for para ti, e para teus filhos em herança perpétua: porquanto cumpriste seguindo ao SENHOR meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 10, 'Agora bem, o SENHOR me fez viver, como ele disse, estes quarenta e cinco anos, desde o tempo que o SENHOR falou estas palavras a Moisés, quando Israel andava pelo deserto: e agora, eis que sou hoje dia de oitenta e cinco anos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 11, 'Porém ainda hoje estou tão forte como o dia que Moisés me enviou: qual era então minha força, tal é agora, para a guerra, e para sair e para entrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 12, 'Dá-me, pois, agora este monte, do qual falou o SENHOR aquele dia; porque tu ouviste naquele dia que os anaquins estão ali, e grandes e fortes cidades. Talvez o SENHOR seja comigo, e os expulsarei como o SENHOR disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 13, 'Josué então lhe abençoou, e deu a Calebe filho de Jefoné a Hebrom por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 14, 'Portanto Hebrom foi de Calebe, filho de Jefoné quenezeu, em herança até hoje; porque cumpriu seguindo ao SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 14, 15, 'Mas Hebrom foi antes chamada Quiriate-Arba; foi Arba um homem grande entre os anaquins. E a terra teve repouso das guerras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 1, 'E foi a sorte da tribo dos filhos de Judá, por suas famílias, junto ao termo de Edom, do deserto de Zim ao sul, ao lado do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 2, 'E seu termo da parte do sul foi desde a costa do mar Salgado, desde a baía que está voltada ao sul;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 3, 'E saía até o sul à subida de Acrabim, passando até Zim; e subindo pelo sul até Cades-Barneia, passava a Hebrom, e subindo por Adar dava volta a Carca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 4, 'De ali passava a Azmom, e saía ao ribeiro do Egito; e sai este termo ao ocidente. Este pois vos será o termo do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 5, 'O termo do oriente é o mar Salgado até o fim do Jordão. E o termo da parte do norte, desde a baía do mar, desde o fim do Jordão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 6, 'E sobe este termo por Bete-Hogla, e passa do norte a Bete-Arabá, e daqui sobe este termo à pedra de Boã, filho de Rúben.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 7, 'E torna a subir este termo a Debir desde o vale de Acor: e ao norte olha sobre Gilgal, que está diante da subida de Adumim, a qual está ao sul do ribeiro: e passa este termo às águas de En-Semes, e sai à fonte de Rogel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 8, 'E sobe este termo pelo vale do filho de Hinom ao lado dos jebuseus ao sul: esta é Jerusalém. Logo sobe este termo pelo cume do monte que está diante do vale de Hinom até o ocidente, o qual está ao fim do vale dos gigantes ao norte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 9, 'E rodeia este termo desde o cume do monte até a fonte das águas de Neftoa, e sai às cidades do monte de Efrom, rodeando logo o mesmo termo a Baalá, a qual é Quriate-Jearim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 10, 'Depois torna este termo desde Baalá até o ocidente ao monte de Seir: e passa ao lado do monte de Jearim até o norte, esta é Quesalom, e desce a Bete-Semes, e passa a Timna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 11, 'Sai logo este termo ao lado de Ecrom até o norte; e rodeia o mesmo termo a Sicrom, e passa pelo monte de Baalá, e sai a Jabneel: e sai este termo ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 12, 'O termo do ocidente é o mar grande. Este, pois, é o termo dos filhos de Judá em derredor, por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 13, 'Mas a Calebe, filho de Jefoné, deu parte entre os filhos de Judá, conforme o mandamento do SENHOR a Josué: isto é, a Quiriate-Arba, do pai de Anaque, que é Hebrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 14, 'E Calebe expulsou dali três filhos de Anaque, a Sesai, Aimã, e Talmai, filhos de Anaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 15, 'De aqui subiu aos que moravam em Debir: e o nome de Debir era antes Quiriate-Sefer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 16, 'E disse Calebe: Ao que ferir a Quiriate-Sefer, e a tomar, eu lhe darei a minha filha Acsa por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 17, 'E tomou-a Otniel, filho de Quenaz, irmão de Calebe; e ele lhe deu por mulher a sua filha Acsa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 18, 'E aconteceu que quando a levava, ele a persuadiu que pedisse a seu pai terras para lavrar. Ela então desceu do asno. E Calebe lhe disse: Que tens?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 19, 'E ela respondeu: Dá-me bênção; pois me deste terra de secura, dá-me também fontes de águas. Ele então lhe deu as fontes de acima, e as de abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 20, 'Esta, pois é a herança das tribos dos filhos de Judá por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 21, 'E foram as cidades do termo da tribo dos filhos de Judá até o termo de Edom ao sul: Cabzeel, e Éder, e Jagur,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 22, 'E Quiná, e Dimona, e Adada,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 23, 'E Quedes, e Hazor, e Itnã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 24, 'Zife, e Telém, Bealote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 25, 'E Hazor-Hadata, e Queriote-Hezrom, que é Hazor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 26, 'Amã, e Sema, e Moladá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 27, 'E Hazar-Gada, e Hesmom, e Bete-Pelete,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 28, 'E Hazar-Sual, Berseba, e Biziotiá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 29, 'Baalá, e Iim, e Azém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 30, 'E Eltolade, e Quesil, e Hormá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 31, 'E Ziclague, e Madmana, Sansana,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 32, 'E Lebaote, Silim, e Aim, e Rimom; em todas vinte e nove cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 33, 'Nas planícies, Estaol, e Zorá, e Asná,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 34, 'E Zanoa, e En-Ganim, Tapua, e Enã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 35, 'Jeremote, e Adulão, Socó, e Azeca,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 36, 'E Saaraim, e Aditaim, e Gederá, e Gederotaim; catorze cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 37, 'Zenã, e Hadasa, e Migdal-Gade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 38, 'E Dileã, e Mispá, e Jocteel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 39, 'Laquis, e Bozcate, e Eglom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 40, 'E Cabom, e Laamás, e Quitilis,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 41, 'E Gederote, Bete-Dagom, e Naamá, e Maquedá; dezesseis cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 42, 'Libna, e Eter, e Asã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 43, 'E Iftá, e Asná, e Nezibe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 44, 'E Queila, e Aczibe, e Maressa; nove cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 45, 'Ecrom com suas vilas e suas aldeias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 46, 'Desde Ecrom até o mar, todas as que estão à costa de Asdode com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 47, 'Asdode com suas vilas e suas aldeias: Gaza com suas vilas e suas aldeias até o rio do Egito, e o grande mar com seus termos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 48, 'E nas montanhas, Samir, e Jatir, e Sucote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 49, 'E Dana, e Quiriate-Saná, que é Debir,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 50, 'E Anabe, e Estemo, e Anim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 51, 'E Gósen, e Holom, e Gilo; onze cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 52, 'Arabe, e Dumá, e Esã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 53, 'E Janim, e Bete-Tapua, e Afeca,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 54, 'E Hunta, e Quiriate-Arba, que é Hebrom, e Zior; nove cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 55, 'Maom, Carmelo, e Zife, e Jutá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 56, 'E Jezreel, Jocdeão, e Zanoa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 57, 'Caim, Gibeá, e Timna; dez cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 58, 'Halul, e Bete-Zur, e Gedor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 59, 'E Maarate, e Bete-Anote, e Eltecom; seis cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 60, 'Quriate-Baal, que é Quriate-Jearim, e Rabá; duas cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 61, 'No deserto, Bete-Arabá, Midim, e Secacá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 62, 'E Nibsã, e a cidade do sal, e En-Gedi; seis cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 15, 63, 'Mas aos jebuseus que habitavam em Jerusalém, os filhos de Judá não os puderam desarraigar; antes restaram os jebuseus em Jerusalém com os filhos de Judá, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 1, 'E a porção dos filhos de José saiu desde o Jordão de Jericó até as águas de Jericó até o oriente, ao deserto que sobe de Jericó ao monte de Betel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 2, 'E de Betel sai a Luz, e passa ao termo dos arquitas em Atarote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 3, 'E torna a descer até o mar ao termo dos jafletitas, até o termo de Bete-Horom a de abaixo, e até Gezer; e sai ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 4, 'Receberam, pois, herança os filhos de José, Manassés e Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 5, 'E foi o termo dos filhos de Efraim por suas famílias, foi o termo de sua herança à parte oriental, desde Atarote-Adar até Bete-Horom a de acima:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 6, 'E sai este termo ao mar, e a Micmetá ao norte, e dá volta este termo até o oriente a Taanate-Siló, e daqui passa ao oriente a Janoa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 7, 'E de Janoa desce a Atarote, e a Naarate, e cabe em Jericó, e sai ao Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 8, 'E de Tapua torna este termo até o mar ao ribeiro de Caná, e sai ao mar. Esta é a herança da tribo dos filhos de Efraim por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 9, 'houve também cidades que se apartaram para os filhos de Efraim em meio da herança dos filhos de Manassés, todas cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 16, 10, 'E não expulsaram aos cananeus que habitavam em Gezer; antes restaram os cananeus em meio de Efraim, até hoje, e foram tributários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 1, 'E teve também porção a tribo de Manassés, porque foi primogênito de José. Maquir, primogênito de Manassés, e pai de Gileade, o qual foi homem de guerra, teve a Gileade e a Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 2, 'Tiveram também porção os outros filhos de Manassés conforme suas famílias: os filhos de Abiezer, e os filhos de Helebe, e os filhos de Asriel, e os filhos de Siquém, e os filhos de Héfer, e os filhos de Semida; estes foram os filhos homens de Manassés, filho de José, por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 3, 'Porém Zelofeade, filho de Héfer, filho de Gileade, filho de Maquir, filho de Manassés, não teve filhos, somente filhas, os nomes das quais são estes: Maalá, Noa, Hogla, Milca, e Tirza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 4, 'Estas vieram diante de Eleazar sacerdote, e de Josué filho de Num, e dos príncipes, e disseram: O SENHOR mandou a Moisés que nos desse herança entre nossos irmãos. E ele lhes deu herança entre os irmãos do pai delas, conforme o dito do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 5, 'E caíram a Manassés dez porções a mais da terra de Gileade e de Basã, que está da outra parte do Jordão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 6, 'Porque as filhas de Manassés possuíram herança entre seus filhos: e a terra de Gileade foi dos outros filhos de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 7, 'E foi o termo de Manassés desde Aser até Micmetá, a qual está diante de Siquém; e vai este termo à direita, aos que habitam em Tapua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 8, 'E a terra de Tapua foi de Manassés; mas Tapua, que está junto ao termo de Manassés, é dos filhos de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 9, 'E desce este termo ao ribeiro de Caná, até o sul do ribeiro. Estas cidades de Efraim estão entre as cidades de Manassés: e o termo de Manassés é desde o norte do mesmo ribeiro, e suas saídas são ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 10, 'Efraim ao sul, e Manassés ao norte, e o mar é seu termo: e encontram-se com Aser à parte do norte, e com Issacar ao oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 11, 'Teve também Manassés em Issacar e em Aser a Bete-Seã e suas aldeias, e Ibleão e suas aldeias, e os moradores de Dor e suas aldeias, e os moradores de En-Dor e suas aldeias, e os moradores de Taanaque e suas aldeias, e os moradores de Megido e suas aldeias: três províncias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 12, 'Mas os filhos de Manassés não puderam lançar aos daquelas cidades; antes os cananeus quis habitar na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 13, 'Porém quando os filhos de Israel tomaram forças, fizeram tributários aos cananeus, mas não o expulsaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 14, 'E os filhos de José falaram a Josué, dizendo: Por que me deste por herança uma só porção e uma só parte, sendo eu um povo tão grande e que o SENHOR me abençoou assim até agora?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 15, 'E Josué lhes respondeu: Se és povo tão grande, sobe tu ao monte, e corta para ti ali na terra do ferezeus e dos gigantes, pois que o monte de Efraim é estreito para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 16, 'E os filhos de José disseram: Não nos bastará a nós este monte: e todos os cananeus que habitam a terra da campina, têm carros de ferro; os que estão em Bete-Seã e em suas aldeias, e os que estão no vale de Jezreel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 17, 'Então Josué respondeu à casa de José, a Efraim e Manassés, dizendo: Tu és grande povo, e tens grande força; não terás uma só porção;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 17, 18, 'Mas aquele monte será teu; porque é bosque, e tu o cortarás, e serão teus seus termos: porque tu expulsarás aos cananeus, ainda que tenham carros de ferro, e ainda que sejam fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 1, 'E toda a congregação dos filhos de Israel se juntou em Siló, e assentaram ali o tabernáculo do testemunho, depois que a terra lhes foi sujeita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 2, 'Mas haviam restado nos filhos de Israel sete tribos, às quais ainda não haviam repartido sua possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 3, 'E Josué disse aos filhos de Israel: Até quando sereis negligentes para vir a possuir a terra que vos deu o SENHOR o Deus de vossos pais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 4, 'Assinalai três homens de cada tribo, para que eu os envie, e que eles se levantem, e percorram a terra, e a descrevam conforme suas propriedades, e se voltem a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 5, 'E a dividirão em sete partes: e Judá estará em seu termo ao sul, e os da casa de José estarão no seu ao norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 6, 'Vós, pois, demarcareis a terra em sete partes, e me trareis a descrição aqui, e eu vos lançarei as sortes aqui diante do SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 7, 'Porém os levitas nenhuma parte têm entre vós; porque o sacerdócio do SENHOR é a herança deles: Gade também e Rúben, e a meia tribo de Manassés, já receberam sua herança da outra parte do Jordão ao oriente, a qual lhes deu Moisés servo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 8, 'Então aqueles homens se levantaram e se foram; e Josué deu ordem aos que iam demarcar a terra, dizendo-lhes: Ide, percorrei a terra, e demarcai-a, e voltai a mim, para que eu vos lance as sortes aqui diante do SENHOR em Siló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 9, 'Foram, pois, aqueles homens e passaram pela terra, demarcando-a por cidades em sete partes em um livro, e voltaram a Josué ao acampamento em Siló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 10, 'E Josué lhes lançou as sortes diante do SENHOR em Siló; e ali repartiu Josué a terra aos filhos de Israel por suas porções.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 11, 'E tirou-se a sorte da tribo dos filhos de Benjamim por suas famílias: e saiu o termo de sua porção entre os filhos de Judá e os filhos de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 12, 'E foi o termo deles ao lado do norte desde o Jordão: e sobe aquele termo ao lado de Jericó ao norte; sobe depois ao monte até o ocidente, e vem a sair ao deserto de Bete-Áven:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 13, 'E dali passa aquele termo a Luz, pelo lado de Luz (esta é Betel) até o sul. E desce este termo de Atarote-Adar ao monte que está ao sul de Bete-Horom a de abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 14, 'E torna este termo, e dá volta ao lado do mar, ao sul até o monte que está diante de Bete-Horom ao sul; e vem a sair a Quriate-Baal, que é Quriate-Jearim, cidade dos filhos de Judá. Este é o lado do ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 15, 'E o lado do sul é desde a extremidade de Quriate-Jearim, e sai o termo ao ocidente, e sai à fonte das águas de Neftoa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 16, 'E desce este termo ao fim do monte que está diante do vale do filho de Hinom, que está na campina dos gigantes até o norte: desce logo ao vale de Hinom, ao lado dos jebuseus ao sul, e dali desce à fonte de Rogel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 17, 'E do norte torna e sai a En-Semes, e dali sai a Gelilote, que está diante da subida de Adumim, e descia à pedra de Boã, filho de Rúben:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 18, 'E passa ao lado que está diante da campina do norte, e desce às planícies:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 19, 'E torna a passar este termo pelo lado de Bete-Hogla até o norte, e vem a sair o termo à baía do mar Salgado ao norte, ao fim do Jordão ao sul. Este é o termo do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 20, 'E o Jordão acaba este termo ao lado do oriente. Esta é a herança dos filhos de Benjamim por seus termos ao redor, conforme suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 21, 'As cidades da tribo dos filhos de Benjamim, por suas famílias, foram Jericó, Bete-Hogla, e Emeque-Queziz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 22, 'Bete-Arabá, Zemaraim, e Betel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 23, 'E Avim, e Pará, e Ofra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 24, 'E Quefar-Amonai, Ofni, e Geba; doze cidades com suas aldeias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 25, 'Gibeão, Ramá, Beerote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 26, 'E Mispá, Quefira, e Moza,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 27, 'Requém, Irpeel e Tarala,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 18, 28, 'E Zela, Elefe, Jebus, que é Jerusalém, Gibeá, e Quiriate; catorze cidades com suas aldeias. Esta é a herança dos filhos de Benjamim, conforme suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 1, 'A segunda porção saiu para Simeão, pela tribo dos filhos de Simeão conforme suas famílias; e sua herança foi entre a herança dos filhos de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 2, 'E tiveram em sua herdade a Berseba, Seba, e Moladá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 3, 'Hazar-Sual, Balá, e Azem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 4, 'Eltolade, Betul, e Hormá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 5, 'Ziclague, Bete-Marcabote, e Hazar-Susa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 6, 'Bete-Lebaote, e Saruém; treze cidades com suas aldeias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 7, 'Aim, Rimom, Eter, e Asã; quatro cidades com suas aldeias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 8, 'E todas as aldeias que estavam ao redor destas cidades até Baalate-Beer, que é Ramá do sul. Esta é a herança da tribo dos filhos de Simeão, segundo suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 9, 'Da porção dos filhos de Judá foi tirada a herança dos filhos de Simeão; porquanto a parte dos filhos de Judá era escessiva para eles: assim que os filhos de Simeão tiveram sua herança em meio da deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 10, 'A terceira porção saiu pelos filhos de Zebulom conforme suas famílias: e o termo de sua herança foi até Saride.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 11, 'E seu termo sobe até o mar e até Maralá, e chega até Dabesete, e dali chega ao ribeiro que está diante de Jocneão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 12, 'E tornando de Saride até oriente, o oriente ao termo de Quislote-Tabor, sai a Daberate, e sobe a Jafia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 13, 'E passando dali até o lado oriental a Gate-Hefer e a Ete-Cazim, sai a Rimom rodeando a Neá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 14, 'E daqui torna este termo ao norte a Hanatom, vindo a sair ao vale de Iftá-El;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 15, 'E engloba Catate, e Naalal, e Sinrom, e Idala, e Belém; doze cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 16, 'Esta é a herdade dos filhos de Zebulom por suas famílias; estas cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 17, 'A quarta porção saiu para Issacar, pelos filhos de Issacar conforme suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 18, 'E foi seu termo Jezreel, e Quesulote, e Suném,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 19, 'E Hafaraim, e Siom, e Anaarate,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 20, 'E Rabite, e Quisiom, e Ebes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 21, 'E Remete, e En-Ganim, e En-Hadá e Bete-Pazez;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 22, 'E chega este termo até Tabor, e Saazima, e Bete-Semes; e sai seu termo ao Jordão: dezesseis cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 23, 'Esta é a herança da tribo dos filhos de Issacar conforme suas famílias; estas cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 24, 'E saiu a quinta porção pela tribo dos filhos de Aser por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 25, 'E seu termo foi Helcate, e Hali, e Béten, e Acsafe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 26, 'E Alameleque, e Amade, e Misal; e chega até Carmelo ao ocidente, e a Sior-Libnate;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 27, 'E tornando do oriente a Bete-Dagom, chega a Zebulom, e ao vale de Iftá-El ao norte, a Bete-Emeque, e a Neiel, e sai a Cabul à esquerda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 28, 'E engloba a Hebrom, e Reobe, e Hamom, e Caná, até a grande Sidom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 29, 'E torna dali este termo a Hormá, e até a forte cidade de Tiro, e torna este termo a Hosa, e sai ao mar desde o território de Aczibe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 30, 'Engloba também Umá, e Afeque, e Reobe: vinte e duas cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 31, 'Esta é a herança da tribo dos filhos de Aser por suas famílias; estas cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 32, 'A sexta porção saiu para os filhos de Naftali, pelos filhos de Naftali conforme suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 33, 'E foi seu termo desde Helefe, e Alom-Zaanim, e Adami-Neguebe, e Jabneel, até Lacum; e sai ao Jordão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 34, 'E tornando dali este termo até o ocidente a Aznote-Tabor, passa dali a Hucoque, e chega até Zebulom ao sul, e ao ocidente confina com Aser, e com Judá ao Jordão até o oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 35, 'E as cidades fortes são Zidim, Zer, e Hamate, Racate, e Quinerete,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 36, 'E Adama, e Ramá, e Hazor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 37, 'E Quedes, e Edrei, e En-Hazor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 38, 'E Irom, e Migdal-Ele, e Horém, e Bete-Anate, e Bete-Semes: dezenove cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 39, 'Esta é a herança da tribo dos filhos de Naftali por suas famílias; estas cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 40, 'A sétima porção saiu para a tribo dos filhos de Dã por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 41, 'E foi o termo de sua herança, Zorá, e Estaol, e Ir-Semes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 42, 'E Saalabim, e Aijalom, e Itla,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 43, 'E Elom, e Timna, e Ecrom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 44, 'E Elteque, Gibetom, e Baalate,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 45, 'E Jeúde, e Bene-Beraque, e Gate-Rimom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 46, 'E Me-Jarcom, e Racom, com o termo que está diante de Jope.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 47, 'E faltou-lhes termo aos filhos de Dã; e subiram os filhos de Dã e combateram a Lesém, e tomando-a feriram-na a fio de espada, e a possuíram, e habitaram nela; e chamaram a Lesém, Dã, do nome de Dã seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 48, 'Esta é a herança da tribo dos filhos de Dã conforme suas famílias; estas cidades com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 49, 'E depois que acabaram de repartir a terra em herança por seus termos, deram os filhos de Israel herança a Josué filho de Num em meio deles:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 50, 'Segundo a palavra do SENHOR, lhe deram a cidade que ele pediu, Timnate-Heres, no monte de Efraim; e ele reedificou a cidade, e habitou nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 19, 51, 'Estas são as propriedades que Eleazar sacerdote, e Josué filho de Num, e os principais dos pais, entregaram por sorte em possessão às tribos dos filhos de Israel em Siló diante do SENHOR, à entrada do tabernáculo do testemunho; e acabaram de repartir a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 1, 'E falou o SENHOR a Josué, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 2, 'Fala aos filhos de Israel, dizendo: Assinalai-vos as cidades de refúgio, das quais eu vos falei por Moisés;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 3, 'Para que se acolha ali o homicida que matar a alguém por acidente e não de propósito; que vos sejam por refúgio do vingador do morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 4, 'E o que se refugiar a alguma daquelas cidades se apresentará à porta da cidade, e dirá suas causas, ouvindo-o os anciãos daquela cidade: e eles o receberão consigo dentro da cidade, e lhe darão lugar que habite com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 5, 'E quando o vingador do morto o seguir, não entregarão em sua mão ao homicida, porquanto feriu a seu próximo por acidente, nem teve com ele antes inimizade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 6, 'E ficará naquela cidade até que compareça em juízo diante do ajuntamento, até a morte do grande sacerdote que for naquele tempo: então o homicida voltará e virá à sua cidade e à sua casa e à cidade de onde fugiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 7, 'Então assinalaram a Quedes na Galileia, no monte de Naftali, e a Siquém no monte de Efraim, e a Quiriate-Arba, que é Hebrom, no monte de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 8, 'E da outra parte do Jordão de Jericó, ao oriente, assinalaram a Bezer no deserto, na planície da tribo de Rúben, e a Ramote em Gileade da tribo de Gade, e a Golã em Basã da tribo de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 20, 9, 'Estas foram as cidades assinaladas para todos os filhos de Israel, e para o estrangeiro que morasse entre eles, para que se acolhesse a elas qualquer um que ferisse pessoa por acidente, e não morresse por meio do vingador do morto, até que comparecesse diante do ajuntamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 1, 'E os principais dos pais dos levitas vieram a Eleazar sacerdote, e a Josué filho de Num, e aos principais dos pais das tribos dos filhos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 2, 'E falaram-lhes em Siló na terra de Canaã, dizendo: O SENHOR mandou por Moisés que nos fossem dadas vilas para habitar, com seus campos para nossos animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 3, 'Então os filhos de Israel deram aos levitas de suas possessões, conforme a palavra do SENHOR, estas vilas com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 4, 'E saiu a sorte para as famílias dos coatitas; e foram dadas por porção aos filhos de Arão sacerdote, que eram dos levitas, pela tribo de Judá, pela de Simeão e pela de Benjamim, treze vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 5, 'E aos outros filhos de Coate se deram por porção dez vilas das famílias da tribo de Efraim, e da tribo de Dã, e da meia tribo de Manassés;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 6, 'E aos filhos de Gérson, pelas famílias da tribo de Issacar, e da tribo de Aser, e da tribo de Naftali, e da meia tribo de Manassés em Basã, foram dadas por porção treze vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 7, 'Aos filhos de Merari por suas famílias se deram doze vilas pela tribo de Rúben, e pela tribo de Gade, e pela tribo de Zebulom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 8, 'E assim deram por sorte os filhos de Israel aos levitas estas vilas com seus campos, como o SENHOR o havia mandado por Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 9, 'E da tribo dos filhos de Judá, e da tribo dos filhos de Simeão deram estas vilas que foram nomeadas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 10, 'E a primeira porção foi dos filhos de Arão, da família de Coate, dos filhos de Levi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 11, 'Aos quais deram Quiriate-Arba, do pai de Anaque, a qual é Hebrom, no monte de Judá, com seus campos em seus entornos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 12, 'Mas o campo desta cidade e suas aldeias deram a Calebe filho de Jefoné, por sua possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 13, 'E aos filhos de Arão, o sacerdote, deram a cidade de refúgio para os homicidas, a Hebrom com seus campos; e a Libna com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 14, 'E a Jatir com seus campos, e a Estemoa com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 15, 'A Holom com seus campos, e a Debir com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 16, 'A Aim com seus campos, a Jutá com seus campos, e a Bete-Semes com seus campos; nove vilas destas duas tribos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 17, 'E da tribo de Benjamim, a Gibeom com seus campos, a Geba com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 18, 'A Anatote com seus campos, a Almom com seus campos: quatro vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 19, 'Todas as vilas dos sacerdotes, filhos de Arão, são treze com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 20, 'Mas as famílias dos filhos de Coate, levitas, os que restavam dos filhos de Coate, receberam por porção vilas da tribo de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 21, 'E deram-lhes a Siquém, vila de refúgio para os homicidas, com seus campos, no monte de Efraim; e a Gezer com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 22, 'E a Quibzaim com seus campos, e a Bete-Horom com seus campos: quatro vilas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 23, 'E da tribo de Dã a Elteque com seus campos, a Gibetom com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 24, 'A Aijalom com seus campos, a Gate-Rimom com seus campos: quatro vilas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 25, 'E da meia tribo de Manassés, a Taanaque com seus campos, e a Gate-Rimom com seus campos: duas vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 26, 'Todas as vilas para o resto das famílias dos filhos de Coate foram dez com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 27, 'Aos filhos de Gérson das famílias dos levitas, deram a vila de refúgio para os homicidas, da meia tribo de Manassés: a Golã em Basã com seus campos, e a Beesterá com seus campos: duas vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 28, 'E da tribo de Issacar, a Quisiom com seus campos, a Daberate com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 29, 'A Jarmute com seus campos, e a En-Ganim com seus campos: quatro vilas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 30, 'E da tribo de Aser, a Misal com seus campos, a Abdom com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 31, 'A Helcate com seus campos, e a Reobe com seus campos: quatro vilas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 32, 'E da tribo de Naftali, a vila de refúgio para os homicidas, a Quedes na Galileia com seus campos, a Hamote-Dor com seus campos, e a Cartã com seus campos: três vilas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 33, 'Todas as vilas dos gersonitas por suas famílias foram treze vilas com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 34, 'E às famílias dos filhos de Merari, levitas que restavam, deu-se a eles da tribo de Zebulom, a Jocneão com seus campos, Cartá com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 35, 'Dimna com seus campos, Naalal com seus campos: quatro vilas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 36, 'E da tribo de Rúben, a Bezer com seus campos, a Jaza com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 37, 'A Quedemote com seus campos, e Mefaate com seus campos: quatro vilas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 38, 'Da tribo de Gade, a vila de refúgio para os homicidas, Ramote em Gileade com seus campos, e Maanaim com seus campos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 39, 'Hesbom com seus campos, e Jazer com seus campos: quatro vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 40, 'Todas as vilas dos filhos de Merari por suas famílias, que restavam das famílias dos levitas, foram por suas porções doze vilas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 41, 'E todas as vilas dos levitas em meio da possessão dos filhos de Israel, foram quarenta e oito vilas com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 42, 'E estas cidades estavam separadas a uma da outra cada qual com seus campos ao redor delas: o qual foi em todas estas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 43, 'Assim deu o SENHOR a Israel toda a terra que havia jurado dar a seus pais; e possuíram-na, e habitaram nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 44, 'E o SENHOR lhes deu repouso ao redor, conforme todo o que havia jurado a seus pais: e nenhum de todos os inimigos lhes parou diante, mas sim que o SENHOR entregou em suas mãos a todos os seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 21, 45, 'Não faltou palavra de todas as boas coisas que o SENHOR falou à casa de Israel; tudo se cumpriu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 1, 'Então Josué chamou aos rubenitas e aos gaditas, e à meia tribo de Manassés,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 2, 'E disse-lhes: Vós guardastes tudo o que Moisés servo do SENHOR vos mandou, e obedecestes à minha voz ao todo o que vos mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 3, 'Não deixastes a vossos irmãos nestes muitos dias até hoje, antes guardastes a observância dos mandamentos do SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 4, 'Agora, pois, que o SENHOR vosso Deus deu repouso a vossos irmãos, como se o havia prometido, voltai, e voltai a vossas tendas, à terra de vossas possessões, que Moisés servo do SENHOR vos deu da outra parte do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 5, 'Somente que com diligência cuideis de pôr por obra o mandamento e a lei, que Moisés servo do SENHOR vos intimou: que ameis ao SENHOR vosso Deus, e andeis em todos os seus caminhos; que guardeis seus mandamentos, e vos achegueis a ele, e lhe sirvais de todo o vosso coração e de toda a vossa alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 6, 'E abençoando-os Josué, os enviou: e foram-se a suas tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 7, 'Também à meia tribo de Manassés havia dado Moisés possessão em Basã; mas à outra meia deu Josué herança entre seus irmãos da outra parte do Jordão ao ocidente: e também a estes enviou Josué a suas tendas, depois de havê-los abençoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 8, 'E falou-lhes, dizendo: Voltai-vos a vossas tendas com grandes riquezas, e com grande quantidade de gado, com prata, e com ouro, e bronze, e muitas vestes: reparti com vossos irmãos o despojo de vossos inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 9, 'E os filhos de Rúben e os filhos de Gade, e a meia tribo de Manassés, se voltaram, e partiram-se dos filhos de Israel, de Siló, que está na terra de Canaã, para ir à terra de Gileade, à terra de suas possessões, da qual eram possuidores, segundo a palavra do SENHOR por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 10, 'E chegando aos termos do Jordão, que está na terra de Canaã, os filhos de Rúben e os filhos de Gade, e a meia tribo de Manassés, edificaram ali um altar junto ao Jordão, um altar de grande aparência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 11, 'E os filhos de Israel ouviram dizer como os filhos de Rúben e os filhos de Gade, e a meia tribo de Manassés, haviam edificado um altar diante da terra de Canaã, nos termos do Jordão, à passagem dos filhos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 12, 'O qual quando os filhos de Israel ouviram, juntou-se toda a congregação dos filhos de Israel em Siló, para subir a lutar contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 13, 'E enviaram os filhos de Israel aos filhos de Rúben e aos filhos de Gade e à meia tribo de Manassés na terra de Gileade, a Fineias filho de Eleazar sacerdote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 14, 'E a dez príncipes com ele; um príncipe de cada casa paterna de todas as tribos de Israel, cada um dos quais era chefe de família de seus pais na multidão de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 15, 'Os quais vieram aos filhos de Rúben e aos filhos de Gade, e à meia tribo de Manassés, na terra de Gileade; e falaram-lhes, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 16, 'Toda a congregação do SENHOR diz assim: Que transgressão é esta com que cometestes contra o Deus de Israel, deixando hoje de perseguir ao SENHOR, edificando para vós altar para ser hoje rebeldes contra o SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 17, 'Foi-nos pouca a maldade de Peor, da qual não estamos ainda limpos até hoje, pela qual foi a mortandade na congregação do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 18, 'E vós vos desviais hoje de perseguir ao SENHOR; mas será que vós vos rebelareis hoje contra o SENHOR, e amanhã se irará ele contra toda a congregação de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 19, 'Que se vos parece que a terra de vossa possessão é imunda, passai-vos à terra da possessão do SENHOR, na qual está o tabernáculo do SENHOR, e tomai possessão entre nós; mas não vos rebeleis contra o SENHOR, nem vos rebeleis contra nós, edificando para vós um altar diferente do altar do SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 20, 'Não cometeu Acã, filho de zerá, transgressão no anátema, e veio ira sobre toda a congregação de Israel? E aquele homem não pereceu sozinho em sua iniquidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 21, 'Então os filhos de Rúben e os filhos de Gade, e a meia tribo de Manassés, responderam e disseram aos principais da multidão de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 22, 'O Deus dos deuses, o SENHOR, o Deus dos deuses, o SENHOR, ele sabe, e Israel saberá; se é por rebelião ou por transgressão contra o SENHOR, não nos salves hoje,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 23, 'se edificamos para nós um altar para deixarmos de seguir o SENHOR, ou para sacrificar holocausto ou oferta de alimentos, ou para oferecer sobre ele sacrifícios pacíficos, que o próprio SENHOR nos castigue por isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 24, 'Porém o fizemos por temor disto, dizendo: Amanhã os vossos filhos dirão aos nossos filhos: Que tendes vós com o SENHOR, o Deus de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 25, 'O SENHOR pôs por termo o Jordão entre nós e vós, ó filhos de Rúben e filhos de Gade; vós não tendes parte no SENHOR; e assim os vossos filhos farão que nossos filhos não temam ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 26, 'Por isso dissemos: Façamos agora para edificar-nos um altar, não para holocausto nem para sacrifício,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 27, 'Mas, sim, para que seja um testemunho entre nós e vós, e entre os que virão depois de nós, de que podemos exercer o serviço do SENHOR diante dele com nossos holocaustos, com nossos sacrifícios, e com as nossas ofertas pacíficas; e não digam amanhã vossos filhos aos nossos: Vós não tendes parte com o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 28, 'Nós, pois, dissemos: Se acontecer que tal digam a nós, ou a nossas gerações no porvir, então responderemos: Olhai a réplica do altar do SENHOR, o qual os nossos pais fizeram, não para holocaustos ou sacrifícios, mas, sim, para que fosse testemunho entre nós e vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 29, 'Nunca tal aconteça que nos rebelemos contra o SENHOR, ou que nos deixemos hoje de seguir ao SENHOR, edificando um altar para holocaustos, para ofertas de alimentos, ou para sacrifício, além do altar do SENHOR, nosso Deus, que está diante do seu tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 30, 'E ouvindo Fineias, o sacerdote, e os príncipes da congregação, e os chefes da multidão de Israel que com ele estavam, as palavras que falaram os filhos de Rúben e os filhos de Gade e os filhos de Manassés, satisfizeram-se com isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 31, 'E disse Fineias, filho do sacerdote Eleazar, aos filhos de Rúben, aos filhos de Gade, e aos filhos de Manassés: Hoje temos entendido que o SENHOR está entre nós, pois não intentastes esta traição contra o SENHOR. Agora livrastes os filhos de Israel da mão do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 32, 'E Fineias, filho do sacerdote Eleazar, e os príncipes, voltaram da presença dos filhos de Rúben, e da presença dos filhos de Gade, da terra de Gileade à terra de Canaã, aos filhos de Israel; e trouxeram-lhes a resposta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 33, 'E o negócio pareceu bem aos filhos de Israel, e os filhos de Israel bendisseram a Deus; e não falaram mais de subir contra eles em guerra, para destruir a terra em que habitavam os filhos de Rúben e os filhos de Gade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 22, 34, 'E os filhos de Rúben e os filhos de Gade puseram por nome ao altar Ede; porque é testemunho entre nós que o SENHOR é Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 1, 'E aconteceu, passados muitos dias depois que o SENHOR deu repouso a Israel de todos os seus inimigos ao redor, que Josué, sendo velho, e cheio de dias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 2, 'Chamou a todo Israel, a seus anciãos, a seus príncipes, a seus juízes e a seus oficiais, e disse-lhes: Eu sou já velho e cheio de dias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 3, 'E vós vistes tudo o que o SENHOR vosso Deus fez com todas estas nações em vossa presença; porque o SENHOR vosso Deus lutou por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 4, 'Eis que vos reparti por sorteio, em herança para vossas tribos, estas nações, tanto as destruídas como as que ficam, desde o Jordão até o grande mar até onde o sol se põe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 5, 'E o SENHOR vosso Deus as expulsará de diante de vós, e as lançará de vossa presença: e vós possuireis suas terras, como o SENHOR vosso Deus vos disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 6, 'Esforçai-vos, pois, muito a guardar e fazer tudo o que está escrito no livro da lei de Moisés, sem apartar-vos dele nem à direita nem à esquerda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 7, 'Que quando entrardes a estas nações que restaram convosco, não façais menção nem jureis pelo nome de seus deuses, nem os sirvais, nem vos inclineis a eles:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 8, 'Mas ao SENHOR vosso Deus vos achegareis, como fizestes até hoje;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 9, 'Pois o SENHOR expulsou diante de vós grandes e fortes nações, e até hoje ninguém há podido resistir diante de vosso rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 10, 'Um homem de vós perseguirá a mil: porque o SENHOR vosso Deus luta por vós, como ele vos disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 11, 'Portanto, cuidai muito por vossas almas, que ameis ao SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 12, 'Porque se vos apartardes, e vos achegardes ao que resta daquelas nações que restaram convosco, e se estabelecerdes com elas matrimônios, e entrardes a elas, e elas a vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 13, 'Sabei que o SENHOR vosso Deus não expulsará mais estas nações diante de vós; antes vos serão por laço, e por tropeço, e por açoite para vossos lados, e por espinhos para vossos olhos, até que pereçais desta boa terra que o SENHOR vosso Deus vos deu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 14, 'E eis que eu estou para entrar hoje pelo caminho de toda a terra: reconhecei, pois, com todo o vosso coração e com toda vossa alma, que não se perdeu uma palavra de todas a boas palavras que o SENHOR vosso Deus disse de vós; todas vieram até vós, nenhuma delas se perdeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 15, 'Mas será, que quando veio sobre vós toda palavra boa que o SENHOR vosso Deus vos havia dito, assim também o SENHOR trará sobre vós toda palavra má, até destruir-vos de sobre a boa terra que o SENHOR vosso Deus vos deu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 23, 16, 'Quando transgredirdes o pacto do SENHOR vosso Deus que ele vos mandou, indo e honrando deuses alheios, e inclinando-vos a eles. E o furor do SENHOR se inflamará contra vós, e logo perecereis desta boa terra que ele vos deu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 1, 'E juntando Josué todas as tribos de Israel em Siquém, chamou aos anciãos de Israel, e a seus príncipes, a seus juízes, e a seus oficiais; e apresentaram-se diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 2, 'E disse Josué a todo o povo: Assim diz o SENHOR, Deus de Israel: Vossos pais habitaram antigamente da outra parte do rio, a saber, Terá, pai de Abraão e de Naor; e serviam a deuses estranhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 3, 'E eu tomei a vosso pai Abraão da outra parte do rio, e trouxe-o por toda a terra de Canaã, e aumentei sua geração, e dei-lhe a Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 4, 'E a Isaque dei a Jacó e a Esaú: e a Esaú dei o monte de Seir, que o possuísse: mas Jacó e seus filhos desceram ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 5, 'E eu enviei a Moisés e a Arão, e feri ao Egito, ao modo que o fiz em meio dele, e depois vos tirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 6, 'E tirei a vossos pais do Egito: e quando chegaram ao mar, os egípcios seguiram a vossos pais até o mar Vermelho com carros e cavalaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 7, 'E quando eles clamaram ao SENHOR, ele pôs escuridão entre vós e os egípcios, e fez vir sobre eles o mar, a qual os cobriu: e vossos olhos viram o que fiz em Egito. Depois estivestes muitos dias no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 8, 'E vos introduzi na terra dos amorreus, que habitavam da outra parte do Jordão, os quais lutaram contra vós; mas eu os entreguei em vossas mãos, e possuístes sua terra, e os destruí de diante de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 9, 'E levantou-se depois Balaque filho de Zipor, rei dos moabitas, e lutou contra Israel; e mandou chamar a Balaão filho de Beor, para que vos amaldiçoasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 10, 'Mas eu não quis escutar a Balaão, antes vos abençoou repetidamente, e vos livre de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 11, 'E passado o Jordão, viestes a Jericó; e os moradores de Jericó lutaram contra vós: os amorreus, perizeus, cananeus, heteus, girgaseus, heveus, e jebuseus: e eu os entreguei em vossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 12, 'E enviei vespas diante de vós, os quais os expulsaram de diante de vós, a saber, aos dois reis dos amorreus; não com tua espada, nem com teu arco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 13, 'E vos dei a terra pela qual nada trabalhastes, e as cidades que não edificastes, nas quais morais; e das vinhas e olivais que não plantastes, comeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 14, 'Agora, pois, temei ao SENHOR, e servi-o com integridade e em verdade; e tirai do meio os deuses aos quais serviram vossos pais da outra parte do rio, e em Egito; e servi ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 15, 'E se mal vos parece servir ao SENHOR, escolhei hoje a quem sirvais; se aos deuses a os quais serviram vossos pais, quando estiveram da outra parte do rio, ou aos deuses dos amorreus em cuja terra habitais: que eu e minha casa serviremos ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 16, 'Então o povo respondeu, e disse: Nunca tal aconteça que deixemos ao SENHOR para servir a outros deuses:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 17, 'Porque o SENHOR nosso Deus é o que tirou a nós e a nossos pais da terra do Egito, da casa de escravidão; o qual diante de nossos olhos fez estas grandes sinais, e nos guardou por todo o caminho por onde andamos, e em todos os povos por entre os quais passamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 18, 'E o SENHOR expulsou de diante de nós a todos os povos, e aos amorreus que habitavam na terra: nós, pois, também serviremos ao SENHOR, porque ele é nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 19, 'Então Josué disse ao povo: Não podereis servir ao SENHOR, porque ele é Deus santo, e Deus zeloso; não tolerará vossas rebeliões e vossos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 20, 'Se deixardes ao SENHOR e servirdes a deuses alheios, se voltará, e vos maltratará, e vos consumirá, depois que vos fez bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 21, 'O povo então disse a Josué: Não, antes ao SENHOR serviremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 22, 'E Josué respondeu ao povo: Vós sois testemunhas contra vós mesmos, de que escolhestes para vós ao SENHOR para servir-lhe. E eles responderam: Testemunhas somos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 24, 23, 'Tirai, pois, agora os deuses alheios que estão entre vós, e inclinai vosso coração ao SENHOR Deus de Israel.')
